import { useEffect, useMemo, useRef, useState } from 'react';
import { useApp } from '../../contexts/AppContext';

// Bottom-right "alarm" card for overdue maintenance. Shows on every page,
// stays until the user snoozes / dismisses it, and comes back when the
// snooze ends or when more assets become overdue.
const KEY = 'rfid_maint_alarm';   // { until: ms, count: n }

const readSnooze = () => { try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch { return {}; } };
const writeSnooze = v => { try { localStorage.setItem(KEY, JSON.stringify(v)); } catch {} };

const chime = () => {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    [[880, 0], [660, 0.22], [880, 0.44]].forEach(([f, t]) => {
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine'; o.frequency.value = f;
      g.gain.setValueAtTime(0.001, ctx.currentTime + t);
      g.gain.exponentialRampToValueAtTime(0.18, ctx.currentTime + t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + t + 0.2);
      o.connect(g).connect(ctx.destination);
      o.start(ctx.currentTime + t); o.stop(ctx.currentTime + t + 0.22);
    });
    setTimeout(() => ctx.close(), 900);
  } catch {}
};

export default function MaintenanceAlarm({ onView }) {
  const { assets = [], settings, profile } = useApp();
  const enabled = settings?.maintAlarm !== false;
  const sound = settings?.maintAlarmSound !== false;
  const snoozeMin = Number(settings?.maintSnoozeMinutes) || 60;
  const SNOOZE_MS = snoozeMin * 60_000;
  const remindHour = settings?.maintRemindHour ?? 8;
  const roles = settings?.maintAlarmRoles || 'all';
  const role = profile?.role;
  const allowed = roles === 'all' || (roles === 'admin' ? role === 'Admin' : role === 'Admin' || role === 'Operator');
  const snoozeLabel = snoozeMin < 60 ? `${snoozeMin} min` : `${snoozeMin / 60} h`;
  const [tick, setTick] = useState(0);
  const [open, setOpen] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const rang = useRef(false);

  useEffect(() => { const t = setInterval(() => setTick(x => x + 1), 60_000); return () => clearInterval(t); }, []);

  const overdue = useMemo(() => {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    return assets
      .filter(a => a.next_maintenance_date && a.status !== 'Decommissioned' && new Date(a.next_maintenance_date) < today)
      .map(a => ({ ...a, days: Math.floor((today - new Date(a.next_maintenance_date)) / 86400000) }))
      .sort((a, b) => b.days - a.days);
  }, [assets]);

  useEffect(() => {
    if (!overdue.length || !enabled || !allowed) { setOpen(false); return; }
    const s = readSnooze();
    const snoozed = s.until && Date.now() < s.until && overdue.length <= (s.count || 0);
    if (!snoozed && !open) {
      setOpen(true);
      if (!rang.current) { rang.current = true; if (sound) chime(); }
    }
  }, [overdue.length, tick, enabled, allowed]); // eslint-disable-line react-hooks/exhaustive-deps

  if (!open || !overdue.length) return null;

  const snooze = ms => { writeSnooze({ until: Date.now() + ms, count: overdue.length }); setOpen(false); rang.current = false; setExpanded(false); };
  const tomorrow = () => { const d = new Date(); d.setDate(d.getDate() + 1); d.setHours(remindHour, 0, 0, 0); return d - Date.now(); };
  const list = expanded ? overdue.slice(0, 50) : overdue.slice(0, 3);
  const mobile = typeof window !== 'undefined' && window.innerWidth < 768;

  return (
    <div role="alert" style={{
      position: 'fixed', right: mobile ? 12 : 20, left: mobile ? 12 : 'auto', bottom: mobile ? 80 : 20, zIndex: 9000,
      width: mobile ? 'auto' : 360, background: 'var(--bg-card)', border: '1px solid #e0575780',
      borderLeft: '4px solid #e05757', borderRadius: 12, boxShadow: '0 12px 40px rgba(0,0,0,.35)',
      animation: 'maintAlarmIn .35s ease-out', overflow: 'hidden',
    }}>
      <style>{`@keyframes maintAlarmIn{from{transform:translateY(24px);opacity:0}to{transform:none;opacity:1}}
               @keyframes maintAlarmPulse{0%,100%{opacity:1}50%{opacity:.35}}`}</style>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 14px 8px' }}>
        <span style={{ fontSize: 20, animation: 'maintAlarmPulse 1.2s infinite' }}>⏰</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#e05757' }}>Maintenance Overdue</div>
          <div style={{ fontSize: 12, color: 'var(--text-dim)' }}>{overdue.length} asset{overdue.length > 1 ? 's' : ''} past due date</div>
        </div>
        <button onClick={() => snooze(SNOOZE_MS)} title={`Dismiss (snooze ${snoozeLabel})`}
          style={{ background: 'none', border: 'none', color: 'var(--text-dim)', fontSize: 18, cursor: 'pointer', lineHeight: 1 }}>✕</button>
      </div>

      <div style={{ maxHeight: expanded ? 240 : 'none', overflowY: 'auto', borderTop: '1px solid var(--border)' }}>
        {list.map(a => (
          <div key={a.id} style={{ display: 'flex', justifyContent: 'space-between', gap: 10, padding: '8px 14px', borderBottom: '1px solid var(--border)', fontSize: 12 }}>
            <div style={{ minWidth: 0 }}>
              <div style={{ color: 'var(--text)', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.name}</div>
              <div style={{ color: 'var(--text-dim)', fontSize: 11 }}>{a.currentFacilityName || '—'}</div>
            </div>
            <div style={{ color: '#e05757', fontWeight: 700, whiteSpace: 'nowrap' }}>{a.days}d overdue</div>
          </div>
        ))}
      </div>
      {overdue.length > 3 && (
        <button onClick={() => setExpanded(e => !e)}
          style={{ width: '100%', background: 'none', border: 'none', borderBottom: '1px solid var(--border)', color: 'var(--text-muted)', fontSize: 11, padding: 6, cursor: 'pointer' }}>
          {expanded ? 'Show less ▲' : `+ ${overdue.length - 3} more ▼`}{expanded && overdue.length > 50 ? ` (first 50 of ${overdue.length})` : ''}
        </button>
      )}

      <div style={{ display: 'flex', gap: 6, padding: 10 }}>
        <button className="btn" style={{ flex: 1, fontSize: 11, padding: '7px 6px', background: 'none', border: '1px solid var(--border)', color: 'var(--text-muted)' }} onClick={() => snooze(SNOOZE_MS)}>Snooze {snoozeLabel}</button>
        <button className="btn" style={{ flex: 1, fontSize: 11, padding: '7px 6px', background: 'none', border: '1px solid var(--border)', color: 'var(--text-muted)' }} onClick={() => snooze(tomorrow())}>Tomorrow</button>
        <button className="btn" style={{ flex: 1.3, fontSize: 11, padding: '7px 6px', background: '#e05757', color: '#fff' }} onClick={() => { snooze(SNOOZE_MS); onView?.(); }}>View assets</button>
      </div>
    </div>
  );
}
