import { useMemo, useRef, useState } from 'react';
import { useApp } from '../../contexts/AppContext';
import { useTenant } from '../../contexts/TenantContext';
import { assetsService } from '../../services/assets.service';
import { parseCSV, downloadCSV } from '../../lib/csv';

const CHUNK = 200;
const STD_COLS = ['name', 'type', 'brand', 'model', 'serial_no', 'vendor', 'condition', 'value', 'quantity', 'quantity_unit',
  'facility', 'epc', 'purchase_date', 'warranty_expiry', 'next_maintenance_date', 'maintenance_interval', 'notes'];
const ISO_COLS = ['name', 'tag_no', 'brand', 'model', 'serial_no', 'vendor', 'condition', 'quantity', 'quantity_unit',
  'facility', 'platform', 'location_detail', 'phe_type', 'year_built', 'preventive_maintenance', 'epc',
  'purchase_date', 'warranty_expiry', 'next_maintenance_date', 'maintenance_interval', 'notes'];
const REQUIRED = ['name', 'facility'];
const DATE_COLS = ['purchase_date', 'warranty_expiry', 'next_maintenance_date'];
const NUM_COLS = ['value', 'quantity', 'year_built'];
// Common header spellings → canonical key
const ALIAS = {
  assetname: 'name', equipmentname: 'name', serial: 'serial_no', serialno: 'serial_no', serialnumber: 'serial_no',
  facilityname: 'facility', facilitycode: 'facility', location: 'facility', epccode: 'epc', rfid: 'epc', tag: 'epc',
  tagno: 'tag_no', unit: 'quantity_unit', qty: 'quantity', nextmaintenance: 'next_maintenance_date',
  warranty: 'warranty_expiry', purchasedate: 'purchase_date', yearbuilt: 'year_built', remarks: 'notes',
  price: 'value', unitprice: 'value', cost: 'value', amount: 'value', valuemyr: 'value', manufacturer: 'brand', make: 'brand',
  supplier: 'vendor', status: 'condition', description: 'notes', comments: 'notes',
};
const EXACT_ONLY = new Set(['unit', 'tag', 'make', 'status', 'location']);   // too generic to match inside longer headers
const norm = h => h.toLowerCase().replace(/[^a-z0-9]/g, '');
// Best guess for a CSV header: exact / alias match, else the longest field name contained in it.
const guessKey = (h, cols) => {
  const n = norm(h);
  if (!n) return '';
  const exact = cols.find(c => norm(c) === n) || ALIAS[n];
  if (exact && cols.includes(exact)) return exact;
  const alias = Object.keys(ALIAS).filter(a => !EXACT_ONLY.has(a) && n.includes(a) && cols.includes(ALIAS[a])).sort((a, b) => b.length - a.length)[0];
  const col = cols.filter(c => n.includes(norm(c))).sort((a, b) => b.length - a.length)[0];
  if (alias && (!col || alias.length > norm(col).length)) return ALIAS[alias];
  return col || '';
};

// Accepts YYYY-MM-DD, DD/MM/YYYY, DD-MM-YYYY → YYYY-MM-DD, or null if invalid.
const toISODate = v => {
  const s = v.trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  let y, mo, d;
  if (m) [, y, mo, d] = m;
  else if ((m = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/))) [, d, mo, y] = m;
  else return null;
  const dt = new Date(Date.UTC(+y, +mo - 1, +d));
  if (dt.getUTCMonth() !== +mo - 1 || dt.getUTCDate() !== +d) return null;
  return dt.toISOString().slice(0, 10);
};

export default function BulkImportModal({ onClose, types = [], conditions = [] }) {
  const { assets, setAssets, facilities, profile, showToast } = useApp();
  const { org, canAddAsset } = useTenant();
  const isISO = org?.asset_profile === 'iso55000';
  const COLS = isISO ? ISO_COLS : STD_COLS;

  const [fileName, setFileName] = useState('');
  const [sheet, setSheet] = useState(null);     // { header, data }
  const [mapping, setMapping] = useState([]);   // field key per CSV column ('' = ignore)
  const [showMap, setShowMap] = useState(false);
  const [parseErr, setParseErr] = useState('');
  const [drag, setDrag] = useState(false);
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState(null);   // { ok, failed: [] }
  const [onlyErrors, setOnlyErrors] = useState(false);
  const fileRef = useRef(null);

  const downloadTemplate = () => {
    const fac = facilities[0]?.name || 'Main Warehouse';
    const ex = isISO
      ? [{ name: 'Chilled Water Exchanger', tag_no: 'E-1001', brand: 'Alfa Laval', model: 'M10', serial_no: 'SN-001', condition: 'Good', quantity: 1, quantity_unit: 'unit', facility: fac, platform: 'Platform A', location_detail: 'Deck 2', phe_type: 'Plate', year_built: 2019, preventive_maintenance: 'Quarterly inspection', next_maintenance_date: '2027-01-15', maintenance_interval: 'Quarterly' },
         { name: 'Sea Water Pump', tag_no: 'P-2002', brand: 'Grundfos', condition: 'Fair', quantity: 2, quantity_unit: 'unit', facility: fac, epc: 'E28011700000020A1B2C3D4E' }]
      : [{ name: 'Dell Laptop XPS15', type: types[0] || 'Laptop', brand: 'Dell', model: 'XPS 15', serial_no: 'SN-12345', vendor: 'Dell MY', condition: 'Good', value: 5200, quantity: 1, quantity_unit: 'unit', facility: fac, epc: 'E28011700000020A1B2C3D4E', purchase_date: '2026-01-10', warranty_expiry: '2029-01-10', next_maintenance_date: '2027-01-10', maintenance_interval: 'Yearly', notes: 'Finance dept' },
         { name: 'Forklift 2T', type: types[1] || types[0] || 'Equipment', brand: 'Toyota', condition: 'Good', value: 45000, facility: fac }];
    downloadCSV([COLS.map(c => (REQUIRED.includes(c) ? c + '*' : c)), ...ex.map(r => COLS.map(c => r[c] ?? ''))],
      `asset-import-template${isISO ? '-iso' : ''}.csv`);
  };

  const validate = (keys, data) => {

    const facIdx = new Map();
    facilities.forEach(f => { facIdx.set(f.name?.trim().toLowerCase(), f); if (f.code) facIdx.set(String(f.code).trim().toLowerCase(), f); });
    const existingEpc = new Set(assets.map(a => (a.epc || '').toUpperCase()).filter(Boolean));
    const seenEpc = new Map();
    const typeSet = new Set(types.map(t => t.toLowerCase()));
    const condSet = new Set(conditions.map(c => (c.name || c).toLowerCase()));

    return data.map((cells, i) => {
      const r = {}; keys.forEach((k, j) => { if (k) r[k] = (cells[j] ?? '').trim(); });
      const errors = [], warnings = [];
      if (!r.name) errors.push('Name is required');
      const fac = r.facility ? facIdx.get(r.facility.toLowerCase()) : null;
      if (!r.facility) errors.push('Facility is required');
      else if (!fac) errors.push(`Facility "${r.facility}" not found`);
      if (r.epc) {
        r.epc = r.epc.replace(/\s/g, '').toUpperCase();
        if (!/^[0-9A-F]+$/.test(r.epc)) errors.push('EPC must be hex (0-9, A-F)');
        else if (existingEpc.has(r.epc)) errors.push('EPC already used by another asset');
        else if (seenEpc.has(r.epc)) errors.push(`Duplicate EPC (same as row ${seenEpc.get(r.epc)})`);
        else seenEpc.set(r.epc, i + 2);
      }
      DATE_COLS.forEach(c => { if (r[c]) { const d = toISODate(r[c]); if (d) r[c] = d; else errors.push(`${c} "${r[c]}" is not a valid date (use YYYY-MM-DD)`); } });
      NUM_COLS.forEach(c => { if (r[c]) { const n = Number(r[c].replace(/,/g, '')); if (isNaN(n)) errors.push(`${c} must be a number`); else r[c] = n; } });
      if (!isISO && r.type && typeSet.size && !typeSet.has(r.type.toLowerCase())) warnings.push(`New type "${r.type}"`);
      if (r.condition && condSet.size && !condSet.has(r.condition.toLowerCase())) warnings.push(`New condition "${r.condition}"`);
      return { line: i + 2, data: r, fac, errors, warnings };
    });
  };

  const loadFile = file => {
    if (!file) return;
    setParseErr(''); setSheet(null); setResult(null); setFileName(file.name);
    if (!/\.csv$/i.test(file.name)) { setParseErr('Please upload a .csv file. In Excel: File → Save As → "CSV UTF-8 (Comma delimited)".'); return; }
    const reader = new FileReader();
    reader.onload = () => {
      const all = parseCSV(reader.result);
      if (all.length < 2) { setParseErr('The file has no data rows.'); return; }
      if (all.length - 1 > 5000) { setParseErr(`Too many rows (${all.length - 1}). Split into files of 5000 or fewer.`); return; }
      const header = all[0].map(h => h.trim());
      const keys = header.map(h => guessKey(h, COLS));
      // a field can only come from one column — keep the first match
      keys.forEach((k, i) => { if (k && keys.indexOf(k) !== i) keys[i] = ''; });
      setMapping(keys); setSheet({ header, data: all.slice(1) });
      setShowMap(header.some((h, i) => h && !keys[i]) || REQUIRED.some(r => !keys.includes(r)));
    };
    reader.onerror = () => setParseErr('Could not read the file.');
    reader.readAsText(file);
  };

  const missingReq = REQUIRED.filter(r => !mapping.includes(r));
  const rows = useMemo(() => (sheet && !missingReq.length ? validate(mapping, sheet.data) : null),
    [sheet, mapping]); // eslint-disable-line react-hooks/exhaustive-deps
  const setMap = (i, key) => setMapping(m => m.map((k, j) => (j === i ? key : k === key && key ? '' : k)));
  const valid = useMemo(() => (rows || []).filter(r => !r.errors.length), [rows]);
  const invalid = (rows?.length || 0) - valid.length;
  const limit = canAddAsset(assets.length);
  const overLimit = limit.max != null && limit.max !== -1 && assets.length + valid.length > limit.max;

  const runImport = async () => {
    if (!valid.length || overLimit) return;
    setBusy(true); setProgress(0);
    const base = Date.now(), year = new Date().getFullYear();
    const payload = valid.map((r, i) => ({
      ...r.data,
      quantity: r.data.quantity ?? (isISO ? 1 : undefined),
      epc: r.data.epc || null,
      condition: r.data.condition || 'Good',
      type: isISO ? (r.data.type || 'Equipment') : (r.data.type || types[0] || 'Other'),
      inventory_number: `INV-${year}-${String(base + i).slice(-6)}`,
      current_facility: r.fac.id,
      current_facility_name: r.fac.name,
      status: 'Available',
      org_id: profile?.org_id,
      _line: r.line,
    }));
    const added = [], failed = [];
    for (let i = 0; i < payload.length; i += CHUNK) {
      const chunk = payload.slice(i, i + CHUNK);
      try {
        added.push(...await assetsService.createMany(chunk.map(({ _line, ...a }) => a)));
      } catch (e) {
        chunk.forEach(a => failed.push({ line: a._line, name: a.name, error: e.message }));
      }
      setProgress(Math.min(payload.length, i + CHUNK) / payload.length);
    }
    if (added.length) setAssets(prev => [...added, ...prev]);
    setResult({ ok: added.length, failed });
    setBusy(false);
    showToast(added.length ? `✓ Imported ${added.length} asset${added.length > 1 ? 's' : ''}` : '❌ Import failed', added.length ? undefined : 'error');
  };

  const downloadErrors = () => {
    const bad = [
      ...(rows || []).filter(r => r.errors.length).map(r => ({ line: r.line, ...r.data, error: r.errors.join('; ') })),
      ...(result?.failed || []).map(f => ({ line: f.line, name: f.name, error: f.error })),
    ];
    downloadCSV([['row', ...COLS, 'error'], ...bad.map(b => [b.line, ...COLS.map(c => b[c] ?? ''), b.error])], 'asset-import-errors.csv');
  };

  const shown = (rows || []).filter(r => !onlyErrors || r.errors.length);
  const previewCols = ['name', isISO ? 'tag_no' : 'type', 'facility', 'epc', 'condition'];
  const btn = { fontSize: 12, padding: '8px 14px', background: 'var(--bg-input)', color: 'var(--text-2)', border: '1px solid var(--border)' };

  return (
    <div className="modal-overlay">
      <div className="modal" style={{ maxWidth: 860, width: '100%' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 18 }}>
          <div>
            <div style={{ fontFamily: "'Syne',sans-serif", fontWeight: 800, fontSize: 16, color: 'var(--text)' }}>Bulk Import Assets</div>
            <div style={{ fontSize: 12, color: 'var(--text-dim)', marginTop: 3 }}>Upload a CSV file to register many assets at once{isISO ? ' (ISO 55000 profile)' : ''}.</div>
          </div>
          <button onClick={onClose} disabled={busy} style={{ background: 'none', border: 'none', color: 'var(--text-3)', fontSize: 20, cursor: 'pointer', lineHeight: 1 }}>✕</button>
        </div>

        {/* Step 1 */}
        <div style={{ display: 'flex', gap: 12, alignItems: 'center', padding: '12px 14px', background: 'var(--bg-input)', border: '1px solid var(--border)', borderRadius: 10, marginBottom: 12, flexWrap: 'wrap' }}>
          <div style={{ flex: 1, minWidth: 220, fontSize: 12, color: 'var(--text-2)' }}>
            <b style={{ color: 'var(--text)' }}>1. Get the template.</b> Fill it in Excel, then <b>File → Save As → CSV UTF-8</b>.
            Required: <b>name</b>, <b>facility</b> (facility name or code). Dates as YYYY-MM-DD.
          </div>
          <button className="btn" style={btn} onClick={downloadTemplate}>⬇ Download template</button>
        </div>

        {/* Step 2 */}
        {!result && (
          <div onClick={() => !busy && fileRef.current?.click()}
            onDragOver={e => { e.preventDefault(); setDrag(true); }} onDragLeave={() => setDrag(false)}
            onDrop={e => { e.preventDefault(); setDrag(false); loadFile(e.dataTransfer.files[0]); }}
            style={{ border: `2px dashed ${drag ? 'var(--accent)' : 'var(--border)'}`, borderRadius: 10, padding: '18px 14px', textAlign: 'center',
                     cursor: busy ? 'default' : 'pointer', marginBottom: 12, background: drag ? 'color-mix(in srgb, var(--accent) 6%, transparent)' : 'transparent' }}>
            <input ref={fileRef} type="file" accept=".csv,text/csv" style={{ display: 'none' }}
              onChange={e => { loadFile(e.target.files[0]); e.target.value = ''; }} />
            <div style={{ fontSize: 13, color: 'var(--text)' }}><b>2. {fileName ? `📄 ${fileName}` : 'Drop your CSV here or click to choose'}</b></div>
            {fileName && <div style={{ fontSize: 11, color: 'var(--text-dim)', marginTop: 3 }}>Click to choose a different file</div>}
          </div>
        )}

        {parseErr && <div style={{ padding: 12, borderRadius: 8, background: 'rgba(224,87,87,.1)', color: 'var(--red)', fontSize: 13, marginBottom: 12 }}>{parseErr}</div>}

        {/* Column matching */}
        {sheet && !result && (showMap || missingReq.length > 0) && (
          <div style={{ border: '1px solid var(--border)', borderRadius: 10, marginBottom: 12, overflow: 'hidden' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', background: 'var(--bg-input)', borderBottom: '1px solid var(--border)', flexWrap: 'wrap' }}>
              <b style={{ fontSize: 13, color: 'var(--text)' }}>Match columns</b>
              <span style={{ fontSize: 12, color: 'var(--text-dim)' }}>Tell us what each column in your file is. Set unwanted columns to “Ignore”.</span>
              <div style={{ flex: 1 }} />
              {!missingReq.length && <button className="btn" style={{ ...btn, padding: '5px 10px' }} onClick={() => setShowMap(false)}>Done ✓</button>}
            </div>
            {missingReq.length > 0 && <div style={{ padding: '8px 14px', fontSize: 12, color: 'var(--red)' }}>Choose which column is: <b>{missingReq.join(', ')}</b> (required)</div>}
            <div style={{ maxHeight: 260, overflowY: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead><tr>{['Column in your file', 'Example', 'Import as'].map(h => <th key={h} style={{ textAlign: 'left', padding: '6px 14px', color: 'var(--text-dim)', fontSize: 11, textTransform: 'uppercase' }}>{h}</th>)}</tr></thead>
                <tbody>
                  {sheet.header.map((h, i) => (
                    <tr key={i} style={{ borderTop: '1px solid var(--border)', opacity: mapping[i] ? 1 : .6 }}>
                      <td style={{ padding: '6px 14px', color: 'var(--text)', fontWeight: 600 }}>{h || <i style={{ color: 'var(--text-dim)' }}>(no header)</i>}</td>
                      <td style={{ padding: '6px 14px', color: 'var(--text-dim)', maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{sheet.data.find(r => r[i]?.trim())?.[i] || '—'}</td>
                      <td style={{ padding: '4px 14px' }}>
                        <select className="sel" value={mapping[i] || ''} onChange={e => setMap(i, e.target.value)} style={{ width: '100%', fontSize: 12, padding: '5px 8px' }}>
                          <option value="">— Ignore —</option>
                          {COLS.map(c => <option key={c} value={c}>{c}{REQUIRED.includes(c) ? ' *' : ''}{mapping.includes(c) && mapping[i] !== c ? '  (used)' : ''}</option>)}
                        </select>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
        {sheet && !result && !showMap && !missingReq.length && (
          <div style={{ fontSize: 12, color: 'var(--text-dim)', marginBottom: 8 }}>
            {mapping.filter(Boolean).length} of {sheet.header.length} columns matched ·{' '}
            <button onClick={() => setShowMap(true)} style={{ background: 'none', border: 'none', color: 'var(--accent)', cursor: 'pointer', fontSize: 12, padding: 0 }}>Adjust columns</button>
          </div>
        )}

        {/* Step 3 — preview */}
        {rows && !result && (
          <>
            <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', marginBottom: 8, fontSize: 13 }}>
              <b style={{ color: 'var(--text)' }}>3. Review</b>
              <span style={{ color: 'var(--accent)' }}>✓ {valid.length} ready</span>
              {invalid > 0 && <span style={{ color: 'var(--red)' }}>✗ {invalid} with errors (will be skipped)</span>}
              <div style={{ flex: 1 }} />
              {invalid > 0 && <label style={{ fontSize: 12, color: 'var(--text-2)', display: 'flex', gap: 6, alignItems: 'center', cursor: 'pointer' }}>
                <input type="checkbox" checked={onlyErrors} onChange={e => setOnlyErrors(e.target.checked)} /> Show errors only</label>}
              {invalid > 0 && <button className="btn" style={{ ...btn, padding: '5px 10px' }} onClick={downloadErrors}>Error report</button>}
            </div>
            <div style={{ maxHeight: 300, overflow: 'auto', border: '1px solid var(--border)', borderRadius: 10 }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead><tr style={{ position: 'sticky', top: 0, background: 'var(--bg-card)' }}>
                  {['Row', '', ...previewCols, 'Issues'].map((h, i) => <th key={i} style={{ textAlign: 'left', padding: '7px 10px', color: 'var(--text-dim)', fontSize: 11, textTransform: 'uppercase', borderBottom: '1px solid var(--border)' }}>{h}</th>)}
                </tr></thead>
                <tbody>
                  {shown.slice(0, 500).map(r => (
                    <tr key={r.line} style={{ borderBottom: '1px solid var(--border)' }}>
                      <td style={{ padding: '6px 10px', color: 'var(--text-dim)' }}>{r.line}</td>
                      <td style={{ padding: '6px 4px' }}>{r.errors.length ? '❌' : '✅'}</td>
                      {previewCols.map(c => <td key={c} style={{ padding: '6px 10px', color: 'var(--text)', maxWidth: 180, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontFamily: c === 'epc' ? 'var(--mono)' : undefined }}>{r.data[c] || '—'}</td>)}
                      <td style={{ padding: '6px 10px', color: r.errors.length ? 'var(--red)' : 'var(--orange)', fontSize: 11 }}>{[...r.errors, ...r.warnings].join('; ')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {shown.length > 500 && <div style={{ padding: 8, textAlign: 'center', fontSize: 11, color: 'var(--text-dim)' }}>Showing first 500 of {shown.length} rows</div>}
            </div>
            {overLimit && <div style={{ padding: 10, borderRadius: 8, background: 'rgba(224,87,87,.1)', color: 'var(--red)', fontSize: 12, marginTop: 10 }}>
              Your plan allows {limit.max} assets — you have {assets.length}, importing {valid.length} would exceed it. Remove rows or upgrade the plan.</div>}
            {busy && <div style={{ height: 6, background: 'var(--bg-input)', borderRadius: 3, marginTop: 12, overflow: 'hidden' }}>
              <div style={{ width: `${Math.round(progress * 100)}%`, height: '100%', background: 'var(--accent)', transition: 'width .3s' }} /></div>}
            <div style={{ display: 'flex', gap: 10, marginTop: 14 }}>
              <button className="btn" style={{ ...btn, flex: 1 }} onClick={onClose} disabled={busy}>Cancel</button>
              <button className="btn" style={{ flex: 2, background: 'var(--accent)', color: '#060b10', opacity: !valid.length || overLimit ? .5 : 1 }}
                onClick={runImport} disabled={busy || !valid.length || overLimit}>
                {busy ? `Importing… ${Math.round(progress * 100)}%` : `Import ${valid.length} asset${valid.length === 1 ? '' : 's'}`}
              </button>
            </div>
          </>
        )}

        {/* Step 4 — result */}
        {result && (
          <div style={{ textAlign: 'center', padding: '16px 0 4px' }}>
            <div style={{ fontSize: 34 }}>{result.failed.length ? '⚠️' : '✅'}</div>
            <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--text)', marginTop: 6 }}>{result.ok} asset{result.ok === 1 ? '' : 's'} imported</div>
            <div style={{ fontSize: 12, color: 'var(--text-dim)', marginTop: 4 }}>
              {invalid > 0 && `${invalid} skipped (validation errors). `}{result.failed.length > 0 && `${result.failed.length} failed to save: ${result.failed[0].error}`}
            </div>
            <div style={{ display: 'flex', gap: 10, justifyContent: 'center', marginTop: 16 }}>
              {(invalid > 0 || result.failed.length > 0) && <button className="btn" style={btn} onClick={downloadErrors}>⬇ Error report</button>}
              <button className="btn" style={{ fontSize: 12, padding: '8px 18px', background: 'var(--accent)', color: '#060b10' }} onClick={onClose}>Done</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
